/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE DF_ORDERS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE DF_MENU CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE DF_CATEGORIES CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE DF_TABLES CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE DF_CUSTOMERS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
CREATE TABLE DF_CUSTOMERS (CUSTOMER_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CUSTOMER_NAME VARCHAR2(100) NOT NULL, PHONE VARCHAR2(15));
CREATE TABLE DF_TABLES (TABLE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, TABLE_NAME VARCHAR2(20) UNIQUE NOT NULL, CAPACITY NUMBER(2) NOT NULL, TABLE_STATUS VARCHAR2(12) DEFAULT 'AVAILABLE' CHECK(TABLE_STATUS IN ('AVAILABLE','OCCUPIED')));
CREATE TABLE DF_CATEGORIES (CATEGORY_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CATEGORY_NAME VARCHAR2(40) UNIQUE NOT NULL);
CREATE TABLE DF_MENU (ITEM_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CATEGORY_ID NUMBER REFERENCES DF_CATEGORIES, ITEM_NAME VARCHAR2(80) NOT NULL, PRICE NUMBER(9,2) NOT NULL CHECK(PRICE>=0), IS_AVAILABLE CHAR(1) DEFAULT 'Y' CHECK(IS_AVAILABLE IN ('Y','N')));
CREATE TABLE DF_ORDERS (ORDER_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CUSTOMER_ID NUMBER REFERENCES DF_CUSTOMERS, TABLE_ID NUMBER REFERENCES DF_TABLES, ORDER_DATE TIMESTAMP DEFAULT SYSTIMESTAMP, ORDER_STATUS VARCHAR2(15) DEFAULT 'PLACED' CHECK(ORDER_STATUS IN ('PLACED','PREPARING','SERVED','CANCELLED')));
CREATE TABLE DF_ORDER_ITEMS (ORDER_ITEM_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ORDER_ID NUMBER REFERENCES DF_ORDERS ON DELETE CASCADE, ITEM_ID NUMBER REFERENCES DF_MENU, QUANTITY NUMBER(4) CHECK(QUANTITY>0), UNIT_PRICE NUMBER(9,2));
